import pytesseract
from PIL import Image
import re

img = Image.open("chart.jpg")
# Use pytesseract to get data
data = pytesseract.image_to_data(img, config='--oem 3 --psm 6', output_type=pytesseract.Output.DICT)
for i in range(len(data['text'])):
    text = data['text'][i].strip()
    if re.match(r'^\(?[a-zA-Z]\)?$', text):
        print(f"Found label '{text}' at ({data['left'][i]}, {data['top'][i]})")
    if 'adversarial' in text.lower():
        print(f"Found adversarial: {text}")
    if 'epoch' in text.lower():
        print(f"Found epoch: {text}")
    if 'accuracy' in text.lower():
        print(f"Found accuracy: {text}")
